function Get-DeviceKey { param([string]$PartNumber,[string]$SerialNumber) return "$PartNumber|$SerialNumber" }; function Get-AssignmentKey { param([string]$PartNumber,[string]$SerialNumber,[string]$Derivat,[string]$IStufe) return "$PartNumber|$SerialNumber|$Derivat|$IStufe" }; function Test-LabelQrMatch { param([string]$LabelPartNumber,[string]$QRPartNumber,[string]$LabelSerialNumber,[string]$QRSerialNumber) if(($LabelPartNumber -eq $QRPartNumber) -and ($LabelSerialNumber -eq $QRSerialNumber)){ return "OK" } else { return "LABEL_QR_MISMATCH" } }
function Get-DuplicateStatus { param([string]$ExistingDeviceKey,[string]$ExistingAssignmentKey,[string]$NewDeviceKey,[string]$NewAssignmentKey) if($ExistingAssignmentKey -eq $NewAssignmentKey){ return "DUPLICATE" } elseif($ExistingDeviceKey -eq $NewDeviceKey){ return "DOUBLE_DERIVATIVE" } else { return "NEW" } }
function Get-ValidationStatus { param([string]$LabelPartNumber,[string]$QRPartNumber,[string]$LabelSerialNumber,[string]$QRSerialNumber,[string]$DuplicateStatus) $LabelQrStatus=Test-LabelQrMatch -LabelPartNumber $LabelPartNumber -QRPartNumber $QRPartNumber -LabelSerialNumber $LabelSerialNumber -QRSerialNumber $QRSerialNumber; if($LabelQrStatus -eq "LABEL_QR_MISMATCH"){ return "LABEL_QR_MISMATCH" }; if($DuplicateStatus -eq "DUPLICATE"){ return "DUPLICATE" }; if($DuplicateStatus -eq "DOUBLE_DERIVATIVE"){ return "DOUBLE_DERIVATIVE" }; return "OK" }
function New-TrackingRecord { param([string]$LabelPartNumber,[string]$QRPartNumber,[string]$LabelSerialNumber,[string]$QRSerialNumber,[string]$Derivat,[string]$IStufe,[string]$DuplicateStatus="NEW") $PartNumber=$LabelPartNumber; $SerialNumber=$LabelSerialNumber; $DeviceKey=Get-DeviceKey -PartNumber $PartNumber -SerialNumber $SerialNumber; $AssignmentKey=Get-AssignmentKey -PartNumber $PartNumber -SerialNumber $SerialNumber -Derivat $Derivat -IStufe $IStufe; $ValidationStatus=Get-ValidationStatus -LabelPartNumber $LabelPartNumber -QRPartNumber $QRPartNumber -LabelSerialNumber $LabelSerialNumber -QRSerialNumber $QRSerialNumber -DuplicateStatus $DuplicateStatus; [pscustomobject]@{PartNumber=$PartNumber;SerialNumber=$SerialNumber;Derivat=$Derivat;IStufe=$IStufe;DeviceKey=$DeviceKey;AssignmentKey=$AssignmentKey;ValidationStatus=$ValidationStatus;DoppelDerivat=($ValidationStatus -eq "DOUBLE_DERIVATIVE")} }
function Save-TrackingRecord { param([pscustomobject]$Record,[switch]$DryRun) $Values=@{Title=$Record.AssignmentKey;DeviceKey=$Record.DeviceKey;AssignmentKey=$Record.AssignmentKey;PartNumber=$Record.PartNumber;SerialNumber=$Record.SerialNumber;Derivat=$Record.Derivat;IStufe=$Record.IStufe;ValidationStatus=$Record.ValidationStatus;DoppelDerivat=$Record.DoppelDerivat}; if($DryRun){Write-Host "[DRY-RUN] Datensatz würde gespeichert werden:"; $Values.GetEnumerator() | Sort-Object Name | ForEach-Object {Write-Host "  $($_.Name): $($_.Value)"}; return}; Add-PnPListItem -List "Steuergeraete" -Values $Values | Out-Null; Write-Host "Datensatz gespeichert:" $Record.AssignmentKey }
function Get-SharePointDuplicateStatus { param([string]$DeviceKey,[string]$AssignmentKey,[switch]$DryRun) if($DryRun){Write-Host "[DRY-RUN] Suche AssignmentKey:" $AssignmentKey; Write-Host "[DRY-RUN] Suche DeviceKey:" $DeviceKey; return "NEW"}; $AssignmentItems=Get-PnPListItem -List "Steuergeraete" -Query "<View><Query><Where><Eq><FieldRef Name='AssignmentKey'/><Value Type='Text'>$AssignmentKey</Value></Eq></Where></Query><RowLimit>1</RowLimit></View>"; if($AssignmentItems.Count -gt 0){return "DUPLICATE"}; $DeviceItems=Get-PnPListItem -List "Steuergeraete" -Query "<View><Query><Where><Eq><FieldRef Name='DeviceKey'/><Value Type='Text'>$DeviceKey</Value></Eq></Where></Query><RowLimit>1</RowLimit></View>"; if($DeviceItems.Count -gt 0){return "DOUBLE_DERIVATIVE"}; return "NEW" }
function Invoke-TrackingImport { param([string]$LabelPartNumber,[string]$QRPartNumber,[string]$LabelSerialNumber,[string]$QRSerialNumber,[string]$Derivat,[string]$IStufe,[switch]$DryRun) $DeviceKey=Get-DeviceKey -PartNumber $LabelPartNumber -SerialNumber $LabelSerialNumber; $AssignmentKey=Get-AssignmentKey -PartNumber $LabelPartNumber -SerialNumber $LabelSerialNumber -Derivat $Derivat -IStufe $IStufe; $DuplicateStatus=Get-SharePointDuplicateStatus -DeviceKey $DeviceKey -AssignmentKey $AssignmentKey -DryRun:$DryRun; $Record=New-TrackingRecord -LabelPartNumber $LabelPartNumber -QRPartNumber $QRPartNumber -LabelSerialNumber $LabelSerialNumber -QRSerialNumber $QRSerialNumber -Derivat $Derivat -IStufe $IStufe -DuplicateStatus $DuplicateStatus; Save-TrackingRecord -Record $Record -DryRun:$DryRun; return $Record }
function ConvertFrom-QRString { param([string]$QRString) $data=@{}; foreach($part in $QRString -split ";"){ if($part -match "="){ $kv=$part -split "=",2; $data[$kv[0].Trim()]=$kv[1].Trim() } }; [pscustomobject]@{PartNumber=$data["PN"];SerialNumber=$data["SN"];Hardware=$data["HW"];Software=$data["SW"]} }
function Invoke-TrackingImportFromQR { param([string]$LabelPartNumber,[string]$LabelSerialNumber,[string]$QRString,[string]$Derivat,[string]$IStufe,[switch]$DryRun) $QR=ConvertFrom-QRString -QRString $QRString; Invoke-TrackingImport -LabelPartNumber $LabelPartNumber -QRPartNumber $QR.PartNumber -LabelSerialNumber $LabelSerialNumber -QRSerialNumber $QR.SerialNumber -Derivat $Derivat -IStufe $IStufe -DryRun:$DryRun }
function ConvertFrom-LabelString { param([string]$LabelString) $data=@{}; foreach($part in $LabelString -split ";"){ if($part -match "="){ $kv=$part -split "=",2; $data[$kv[0].Trim()]=$kv[1].Trim() } }; [pscustomobject]@{PartNumber=$data["PN"];SerialNumber=$data["SN"];Hardware=$data["HW"];Software=$data["SW"]} }
function Invoke-TrackingImportFromStrings { param([string]$LabelString,[string]$QRString,[string]$Derivat,[string]$IStufe,[switch]$DryRun) $Label=ConvertFrom-LabelString -LabelString $LabelString; $QR=ConvertFrom-QRString -QRString $QRString; Invoke-TrackingImport -LabelPartNumber $Label.PartNumber -QRPartNumber $QR.PartNumber -LabelSerialNumber $Label.SerialNumber -QRSerialNumber $QR.SerialNumber -Derivat $Derivat -IStufe $IStufe -DryRun:$DryRun }
function Test-LabelQrMatchExtended { param([string]$LabelPartNumber,[string]$QRPartNumber,[string]$LabelSerialNumber,[string]$QRSerialNumber,[string]$LabelHardware,[string]$QRHardware,[string]$LabelSoftware,[string]$QRSoftware) if(($LabelPartNumber -eq $QRPartNumber) -and ($LabelSerialNumber -eq $QRSerialNumber) -and ($LabelHardware -eq $QRHardware) -and ($LabelSoftware -eq $QRSoftware)){ return "OK" } else { return "LABEL_QR_MISMATCH" } }
function Invoke-TrackingImportExtended { param([string]$LabelString,[string]$QRString,[string]$Derivat,[string]$IStufe,[switch]$DryRun) $Label=ConvertFrom-LabelString -LabelString $LabelString; $QR=ConvertFrom-QRString -QRString $QRString; $DeviceKey=Get-DeviceKey -PartNumber $Label.PartNumber -SerialNumber $Label.SerialNumber; $AssignmentKey=Get-AssignmentKey -PartNumber $Label.PartNumber -SerialNumber $Label.SerialNumber -Derivat $Derivat -IStufe $IStufe; $DuplicateStatus=Get-SharePointDuplicateStatus -DeviceKey $DeviceKey -AssignmentKey $AssignmentKey -DryRun:$DryRun; $MatchStatus=Test-LabelQrMatchExtended -LabelPartNumber $Label.PartNumber -QRPartNumber $QR.PartNumber -LabelSerialNumber $Label.SerialNumber -QRSerialNumber $QR.SerialNumber -LabelHardware $Label.Hardware -QRHardware $QR.Hardware -LabelSoftware $Label.Software -QRSoftware $QR.Software; if($MatchStatus -eq "LABEL_QR_MISMATCH"){$FinalStatus="LABEL_QR_MISMATCH"}elseif($DuplicateStatus -eq "DUPLICATE"){$FinalStatus="DUPLICATE"}elseif($DuplicateStatus -eq "DOUBLE_DERIVATIVE"){$FinalStatus="DOUBLE_DERIVATIVE"}else{$FinalStatus="OK"}; [pscustomobject]@{PartNumber=$Label.PartNumber;SerialNumber=$Label.SerialNumber;Derivat=$Derivat;IStufe=$IStufe;LabelHardware=$Label.Hardware;QRHardware=$QR.Hardware;LabelSoftware=$Label.Software;QRSoftware=$QR.Software;DeviceKey=$DeviceKey;AssignmentKey=$AssignmentKey;ValidationStatus=$FinalStatus;DoppelDerivat=($FinalStatus -eq "DOUBLE_DERIVATIVE")} }
function Save-TrackingRecordExtended { param([pscustomobject]$Record,[switch]$DryRun) $Values=@{Title=$Record.AssignmentKey;DeviceKey=$Record.DeviceKey;AssignmentKey=$Record.AssignmentKey;PartNumber=$Record.PartNumber;SerialNumber=$Record.SerialNumber;Derivat=$Record.Derivat;IStufe=$Record.IStufe;LabelHardware=$Record.LabelHardware;QRHardware=$Record.QRHardware;LabelSoftware=$Record.LabelSoftware;QRSoftware=$Record.QRSoftware;ValidationStatus=$Record.ValidationStatus;DoppelDerivat=$Record.DoppelDerivat}; if($DryRun){Write-Host "[DRY-RUN] Datensatz würde gespeichert:"; $Values.GetEnumerator() | Sort-Object Name | ForEach-Object {Write-Host "  $($_.Name): $($_.Value)"}; return}; Add-PnPListItem -List "Steuergeraete" -Values $Values | Out-Null; Write-Host "Datensatz gespeichert:" $Record.AssignmentKey }
